import{escapeHtml,filterNews,newsCard}from './news-utils.mjs';
export function mountNews(root){const $=s=>root.querySelector(s);let feed,page=1;const size=12;let saved;try{saved=new Set(JSON.parse(localStorage.getItem('polymer-atlas-news-favorites')||'[]'))}catch{saved=new Set()}
function render(){const items=filterNews(feed.items,{query:$('#newsSearch').value,material:$('#newsMaterial').value,kind:$('#newsKind').value,month:$('#newsMonth').value,includeBackground:$('#includeBackground').checked}).filter(x=>!$('#savedNews').checked||saved.has(x.id));const pages=Math.max(1,Math.ceil(items.length/size));page=Math.min(page,pages);$('#newsCount').textContent=`${items.length} 条消息`;$('#newsList').innerHTML=items.length?items.slice((page-1)*size,page*size).map(x=>newsCard(x,saved.has(x.id))).join(''):'<div class="empty"><h3>这个筛选下还没有消息</h3><p>试试其他材料或月份，历史消息不会被清空。</p></div>';$('#prevPage').disabled=page===1;$('#nextPage').disabled=page===pages;$('#pageLabel').textContent=`第 ${page} / ${pages} 页`}
function options(selector,values){$(selector).innerHTML+=values.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('')}
for(const id of ['#newsMaterial','#newsKind','#newsMonth'])$(id).addEventListener('change',()=>{if(feed){page=1;render()}});$('#includeBackground').addEventListener('change',()=>{if(feed){page=1;render()}});$('#newsSearch').addEventListener('input',()=>{if(feed){page=1;render()}});$('#clearFilters').addEventListener('click',()=>{for(const id of ['#newsMaterial','#newsKind','#newsMonth','#newsSearch'])$(id).value='';$('#includeBackground').checked=false;$('#savedNews').checked=false;if(feed){page=1;render()}});$('#prevPage').addEventListener('click',()=>{page--;render()});$('#nextPage').addEventListener('click',()=>{page++;render()});
const ready=(async()=>{try{const r=await fetch('news.json',{cache:'no-store'});if(!r.ok)throw Error();feed=await r.json();options('#newsMaterial',[...new Set(feed.items.flatMap(x=>x.materials))].sort());options('#newsKind',[...new Set(feed.items.map(x=>x.kind))].sort());options('#newsMonth',[...new Set(feed.items.map(x=>x.published_at.slice(0,7)))].sort().reverse());$('#total').textContent=`已归档 ${feed.items.length} 条消息`;$('#lastCheck').textContent=`最近检索：${feed.checked_at||feed.updated_at}`;render()}catch{$('#total').textContent='暂时未能载入';$('#newsList').innerHTML='<div class="empty"><h3>动态暂时未能载入</h3><p>请刷新页面重试。</p></div>'}})();

$('#savedNews').addEventListener('change',()=>{page=1;if(feed)render()});$('#newsList').addEventListener('click',ev=>{const b=ev.target.closest('[data-news-save]');if(!b)return;const id=b.dataset.newsSave;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('polymer-atlas-news-favorites',JSON.stringify([...saved]))}catch{}render()});

return {ready};}
export const NEWS_TEMPLATE="<section class=\"intro\"><div><div class=\"eyebrow\">MATERIALS IN MOTION</div><h1>关注材料本身，<br>看懂技术的新变化。</h1><p>新配方、新性能、新用途与回收方法，短读技术要点，再看原文。</p></div></section>\n<div class=\"news-stats\"><span id=\"total\">正在载入…</span><span id=\"lastCheck\"></span><span>历史消息持续保留</span></div>\n<section class=\"toolbar\"><label class=\"search\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"10\" cy=\"10\" r=\"6.5\"/><path d=\"m15 15 5 5\"/></svg><input id=\"newsSearch\" type=\"search\" aria-label=\"搜索材料动态\" placeholder=\"搜索材料、政策或技术关键词…\"></label></section>\n<section class=\"news-filters\" aria-label=\"动态筛选\"><label>材料 <select id=\"newsMaterial\"><option value=\"\">全部材料</option></select></label><label>类型 <select id=\"newsKind\"><option value=\"\">全部类型</option></select></label><label>月份 <select id=\"newsMonth\"><option value=\"\">全部历史</option></select></label><label class=\"background-toggle\"><input type=\"checkbox\" id=\"includeBackground\">包含早期企业与产线消息</label><label><input type=\"checkbox\" id=\"savedNews\">只看收藏</label><button class=\"btn\" id=\"clearFilters\">清除筛选</button></section>\n<div class=\"results-heading\"><div><h2>动态与归档</h2><span id=\"newsCount\" aria-live=\"polite\"></span></div><span>按发布日期 / 政策适用日期排序</span></div><div id=\"newsList\" class=\"news-list\"></div><div class=\"news-pagination\"><button class=\"btn\" id=\"prevPage\" disabled>上一页</button><span id=\"pageLabel\"></span><button class=\"btn\" id=\"nextPage\" disabled>下一页</button></div>\n<footer>新闻摘要仅保留主要事实；企业公告中的预测和性能表述均保留其归属。论文、专利与政策分开标识；收藏保存在当前浏览器，不跨设备同步。<span><a href=\"#materials\" data-view=\"materials\">返回材料图鉴 ↗</a></span></footer>";
